INSERT INTO featurePropertyI18n(featureId,propertyId,locale,value,valueGen) VALUES('eln2027BookDE','ZkXV20T2Bsa7','en','Juno Isabella Flock is a dancer and performance artist who spends her days caring for her ailing husband, and her nights chatting to love scammers online. She’s aware of the risks these men pose – she’s watched a documentary about them – but she’s also discovered a heady freedom in these online conversations, and the things they allow her to say.
INSERT INTO featureProperty(featureId,propertyId,value) VALUES('eln2027BookDE','PLifDO417BbU','Martina Hefter') ON CONFLICT(featureId,propertyId) DO UPDATE SET value=excluded.value WHERE coalesce(trim(featureProperty.value),'')='' AND featureProperty.propertyValueId IS NULL;
