INSERT INTO featureProperty(featureId,propertyId,propertyValueId) VALUES('eln2027BookCZ','j608565AMXfN','fB6nseLK9k71') ON CONFLICT(featureId,propertyId) DO UPDATE SET propertyValueId=excluded.propertyValueId WHERE featureProperty.propertyValueId IS NULL AND coalesce(trim(featureProperty.value),'')='';
INSERT INTO featureProperty(featureId,propertyId) VALUES('eln2027BookCZ','ZkXV20T2Bsa7') ON CONFLICT DO NOTHING;
INSERT INTO featurePropertyI18n(featureId,propertyId,locale,value,valueGen) VALUES('eln2027BookCZ','ZkXV20T2Bsa7','en','Awarded the Magnesia Litera Prose Book of the Year in 2013, CEILINGS is a polyphonic novel kin to the work of Leonora Carrington and Unica Zürn. Taking place in a mental hospital in Prague where the “narrator” is undergoing detox treatment for substance abuse, the borders blur between inner experience and the outer world, between reality and dream. As the walls and ceilings hemming in the desire for freedom fantastically break open as if into the unknown and gender fluidly shifts between brother and sister, who are one and the same, Brabcová’s flights of imagination portray how difficult it is to “come out of oneself” and to engage with the other in a multifarious world that demands it of us, no matter how ambivalently. Ceilings by Zuzana Brabcová is translated from the Czech by Tereza Veverka Novická and published by Twisted Spoon Press in 2025.',0) ON CONFLICT(featureId,propertyId,locale) DO UPDATE SET value=excluded.value,valueGen=0 WHERE coalesce(trim(featurePropertyI18n.value),'')='';
INSERT INTO featureProperty(featureId,propertyId,value) VALUES('eln2027BookCZ','PLifDO417BbU','Zuzana Brabcová') ON CONFLICT(featureId,propertyId) DO UPDATE SET value=excluded.value WHERE coalesce(trim(featureProperty.value),'')='' AND featureProperty.propertyValueId IS NULL;
INSERT INTO featureProperty(featureId,propertyId) VALUES('eln2027BookCZ','w7L3$qPA41ij') ON CONFLICT DO NOTHING;
INSERT INTO featurePropertyI18n(featureId,propertyId,locale,value,valueGen) VALUES('eln2027BookCZ','w7L3$qPA41ij','en','The daughter of two literary historians, Brabcová (1959–2015) was born in Prague. Under the Communist regime, she was denied the right to attend university so she worked as a librarian, a hospital attendant and a cleaner. Following the Velvet Revolution, she worked as an editor. Her first novel Far from the Tree, initially published abroad in 1987, won the inaugural Jiří Orten Prize. Ceilings (2012), recently released in Tereza Veverka Novická’s powerful English translation, was her fourth novel, a vivid, hypnotic account of one woman’s transit through drug rehab. Her writing has been compared to Leonora Carrington and Unica Zürn, whose artwork appears on the cover.',0) ON CONFLICT(featureId,propertyId,locale) DO UPDATE SET value=excluded.value,valueGen=0 WHERE coalesce(trim(featurePropertyI18n.value),'')='';
INSERT INTO featureProperty(featureId,propertyId,propertyValueId) VALUES('eln2027BookCZ','eln2024HostProp','eln2024Host002') ON CONFLICT(featureId,propertyId) DO UPDATE SET propertyValueId=excluded.propertyValueId WHERE featureProperty.propertyValueId IS NULL AND coalesce(trim(featureProperty.value),'')='';
